  }
  if (readiness.ready !== true) {
    throw new Error(`Gateway did not become ready: ${JSON.stringify(readiness)}`);
  }
  const gatewayReadyMs = Math.round(performance.now() - gatewayStartedAt);
  ws = new WebSocket(`ws://127.0.0.1:${port}`);
  const challengePromise = waitForFrame<{ type: "event"; event: "connect.challenge"; payload: { nonce: string } }>(
    ws,
    "Gateway connect challenge",
    (frame): frame is { type: "event"; event: "connect.challenge"; payload: { nonce: string } } =>
      Boolean(frame && typeof frame === "object" && frame.type === "event" && frame.event === "connect.challenge"),
  );
  await new Promise<void>((resolve, reject) => {
    ws!.once("open", resolve);
    ws!.once("error", reject);
  });
  const challenge = await challengePromise;
  const client = { id: "cli", version: "1.0.0", platform: process.platform, mode: "cli" };
  const role = "operator";
  const scopes = ["operator.admin"];
  const identity = loadOrCreateDeviceIdentity({ path: path.join(stateDir, "client", "credentials.sqlite") });
  const signedAt = Date.now();
  const payload = buildDeviceAuthPayloadV3({
