  if (!connected.ok || connected.payload?.type !== "hello-ok") {
    throw new Error(`Gateway connect failed: ${JSON.stringify(connected)}`);
  }

  const requestId = randomUUID();
  const admissionStartedAt = performance.now();
  const acceptedPromise = waitForFrame<any>(ws, "agent admission response", (frame): frame is any =>
    frame?.type === "res" && frame.id === requestId,
