```javascript
import assert from "node:assert/strict";
import { spawn } from "node:child_process";
import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const proofRoot = path.dirname(fileURLToPath(import.meta.url));
const [configPath, selection = "all"] = process.argv.slice(2);
assert(configPath, "Usage: node run.mjs config.json [all|same-schema|stable-upgrade|gateway-seed]");
const config = JSON.parse(await fs.readFile(configPath, "utf8"));
const evidenceRoot = path.join(proofRoot, "runs", config.runName);
await fs.mkdir(evidenceRoot, { recursive: true });
const evidence = { startedAt: new Date().toISOString(), config, selection, phases: [], checks: [] };
const save = () => fs.writeFile(path.join(evidenceRoot, "results.json"), JSON.stringify(evidence, null, 2) + "\n");

async function command(label, args, sourceRoot, stateDir, expectedFailure = false) {
  const homeDir = path.join(stateDir, "isolated-home");
  const tmpDir = path.join(stateDir, "tmp");
  await fs.mkdir(homeDir, { recursive: true });
  await fs.mkdir(tmpDir, { recursive: true });
  await fs.writeFile(path.join(stateDir, "openclaw.json"), '{"plugins":{"enabled":false}}\n');
  const started = performance.now();
  const child = spawn(config.node, args, {
    cwd: sourceRoot,
    env: {
      PATH: `${path.dirname(config.node)}:/usr/bin:/bin:/usr/sbin:/sbin`,
      HOME: homeDir,
      TMPDIR: tmpDir,
      OPENCLAW_STATE_DIR: stateDir,
      OPENCLAW_CONFIG_PATH: path.join(stateDir, "openclaw.json"),
      OPENCLAW_DISABLE_BUNDLED_PLUGINS: "1",
      OPENCLAW_SKIP_PROVIDERS: "1",
      OPENCLAW_SUPERVISOR_MODE: "external",
      NO_COLOR: "1",
    },
    stdio: ["ignore", "pipe", "pipe"],
  });
  let stdout = "";
  let stderr = "";
  child.stdout.on("data", (data) => { stdout += data; });
  child.stderr.on("data", (data) => { stderr += data; });
  const timer = setTimeout(() => child.kill("SIGTERM"), 120_000);
  const code = await new Promise((resolve, reject) => {
    child.once("error", reject);
    child.once("close", resolve);
  }).finally(() => clearTimeout(timer));
  await fs.writeFile(path.join(evidenceRoot, `${label}.stdout.log`), stdout);
  await fs.writeFile(path.join(evidenceRoot, `${label}.stderr.log`), stderr);
  const marker = stdout.split("\n").find((line) => line.startsWith("DATABASE_COMPATIBILITY_RESULT "));
  const result = marker ? JSON.parse(marker.slice("DATABASE_COMPATIBILITY_RESULT ".length)) : undefined;
  evidence.phases.push({ label, code, seconds: (performance.now() - started) / 1000, expectedFailure, result });
  await save();
  assert.equal(code === 0, !expectedFailure, `${label}: exit=${code}; ${JSON.stringify(result?.error)}; ${stderr.slice(-3000)}`);
  if (marker) assert.equal(result.ok, !expectedFailure, `${label}: ${JSON.stringify(result.error)}`);
  console.log(`${label}: ${expectedFailure ? "expected refusal" : "passed"}`);
  return result ?? JSON.parse(stdout);
}

async function worker(label, source, mode, stateDir, storePath, expectedFailure = false) {
  return command(label, [
    "--import", path.join(source, "scripts", "tsx.mjs"),
    path.join(proofRoot, "worker.mjs"), source, mode, stateDir, storePath,
  ], source, stateDir, expectedFailure);
}
async function snapshot(label, stateDir, storePath, backupPath) {
  const result = await command(label, [path.join(proofRoot, "snapshot.mjs"), storePath, ...(backupPath ? [backupPath] : [])], proofRoot, stateDir);
  await fs.writeFile(path.join(evidenceRoot, `${label}.json`), JSON.stringify(result, null, 2) + "\n");
  assert.deepEqual(result.integrity, [{ integrity_check: "ok" }], `${label} integrity`);
  assert.deepEqual(result.foreignKeyViolations, [], `${label} foreign keys`);
  return result;
}
function preserve(before, after, physical) {
  for (const row of before.rows) {
    const found = after.rows.find((entry) => entry.sessionId === row.sessionId && entry.seq === row.seq);
    assert(found, `Missing original event ${row.sessionId}/${row.seq}`);
    assert.equal(found.eventId, row.eventId);
    assert.equal(found.jsonSha256, row.jsonSha256, `Original JSON bytes changed for ${row.eventId}`);
    assert.equal(found.createdAt, row.createdAt);
    if (physical) assert.equal(found.physicalSha256, row.physicalSha256, `Physical payload changed for ${row.eventId}`);
  }
}
function replay(result, timeouts, continuation = false) {
  for (const row of result.rows) {
    assert.equal(row.seedPresent, true);
    assert.equal(row.replayContainsSeed, true);
    assert.equal(row.reportCount, timeouts ? 1 : 0);
    assert.equal(row.replayContainsTimeout, timeouts);
    assert.equal(row.replayContainsPartial, timeouts && row.scenario === "partial-timeout");
    assert.equal(row.replayContainsOldContinuation, continuation);
  }
}

try {
  if (selection === "gateway-seed") {
    const stateDir = path.join(evidenceRoot, "gateway-seed-state");
    const storePath = path.join(stateDir, "agents", "main", "agent", "openclaw-agent.sqlite");
