  const rows = database.prepare("SELECT * FROM transcript_events ORDER BY session_id, seq").all().map((row) => {
    const physical = row.event_json === null ? row.event_zstd : Buffer.from(row.event_json, "utf8");
    const original = row.event_json === null ? zstdDecompressSync(row.event_zstd) : physical;
    const event = JSON.parse(original.toString("utf8"));
    return {
      sessionId: row.session_id,
      seq: row.seq,
      eventId: event.id,
      type: event.type,
      customType: event.customType,
      createdAt: row.created_at,
      encoding: row.event_json === null ? "zstd" : "json-text",
      jsonBytes: original.length,
      jsonSha256: hash(original),
      physicalSha256: hash(physical),
      partial: original.includes(Buffer.from("DATABASE_COMPATIBILITY_PARTIAL_OUTPUT")),
    };
  });
  console.log(JSON.stringify({
    storePath,
    backupPath,
    userVersion: database.prepare("PRAGMA user_version").get().user_version,
    schemaMeta: database.prepare("SELECT role, agent_id, schema_version, app_version FROM schema_meta").all(),
    integrity: database.prepare("PRAGMA integrity_check").all(),
    foreignKeyViolations: database.prepare("PRAGMA foreign_key_check").all(),
    hasCompressedPayloadColumns: columns.has("event_zstd"),
    rows,
  }, null, 2));
} finally {
  database.close();
}

